INSERT INTO knowledge_base (content, source, source_type, metadata, embedding) VALUES
(
    'Engineered Patient Similarity Networks (PSN) and Bipartite Patient-Attribute Graphs on the UCI Heart Disease dataset (297 patients after cleaning) to capture non-i.i.d. (non-independent and identically distributed) clinical relations for heart disease prediction (Graph Learning for Heart Disease Prediction, BMI/CS 775 graduate project at UW-Madison, supervised by Prof. Anthony Gitter and Prof. Sushmita Roy). Graph-based models outperform standard classifiers when patient relationships matter.',
    'graph_learning_project',
    'project',
